class Solution {
    public int[] replaceElements(int[] arr) {
        int n = arr.length;
        int[] res = new int[n];
        for (int i = 0; i < n - 1; i++) {
            int mx = Integer.MIN_VALUE;
            for (int j = i + 1; j < n; j++) mx = Math.max(mx, arr[j]);
            res[i] = mx;
        }
        res[n - 1] = -1;
        return res;
    }
}

